package com.starter.service

import com.fasterxml.jackson.core.type.TypeReference
import com.fasterxml.jackson.databind.ObjectMapper
import org.springframework.jdbc.core.JdbcTemplate
import org.springframework.stereotype.Service

/** A separate keyword query never compares vectors generated by different embedding models. */
@Service
class KeywordSearchService(private val jdbc: JdbcTemplate, private val mapper: ObjectMapper) {
    fun search(query: String, limit: Int, includeContent: Boolean): List<VectorSearchPoint> {
        val terms = Regex("[\\p{L}\\p{N}]+").findAll(query).map { it.value }.distinct().take(32).toList()
        if (terms.isEmpty()) return emptyList()
        val expression = terms.joinToString(" | ") { "'$it'" }
        return jdbc.query("""
            WITH documents AS (
                SELECT i.id::text AS id, jsonb_build_object('entityType', 'folder', 'folderId', i.id::text, 'title', i.title) AS payload,
                    concat_ws(' ', i.title, i.description, i.storage_prefix) AS text
                FROM items i LEFT JOIN storage_connections sc ON sc.id = i.storage_connection_id
                WHERE i.accessible = TRUE AND (sc.id IS NULL OR sc.enabled = TRUE)
                UNION ALL
                SELECT d.id::text, jsonb_build_object('entityType', 'document', 'documentId', d.id::text, 'folderId', i.id::text,
                    'title', d.file_name, 'storagePath', d.storage_path), concat_ws(' ', i.title, d.file_name, d.storage_path, d.content_type)
                FROM storage_documents d JOIN items i ON i.id = d.item_id
                LEFT JOIN storage_connections sc ON sc.id = i.storage_connection_id
                WHERE i.accessible = TRUE AND (sc.id IS NULL OR sc.enabled = TRUE)
                UNION ALL
                SELECT dc.id::text, jsonb_build_object('entityType', 'chunk', 'documentId', d.id::text, 'folderId', i.id::text,
                    'title', d.file_name, 'storagePath', d.storage_path, 'text', dc.content),
                    concat_ws(' ', d.file_name, dc.content)
                FROM document_chunks dc JOIN storage_documents d ON d.id = dc.document_id JOIN items i ON i.id = d.item_id
                LEFT JOIN storage_connections sc ON sc.id = i.storage_connection_id
                WHERE i.accessible = TRUE AND (sc.id IS NULL OR sc.enabled = TRUE) AND ?
            ), query AS (SELECT to_tsquery('simple', ?) AS terms)
            SELECT id, ts_rank(to_tsvector('simple', text), terms)::real AS score, payload::text
            FROM documents CROSS JOIN query WHERE to_tsvector('simple', text) @@ terms
            ORDER BY score DESC, id LIMIT ?
        """.trimIndent(), { rs, _ -> VectorSearchPoint(rs.getString("id"), rs.getFloat("score"),
            mapper.readValue(rs.getString("payload"), object : TypeReference<Map<String, String>>() {})) }, includeContent, expression, limit)
    }
}
